                }))
                .split("\n")
                .map(line => {
                  progress
                  .safe_message(line.to_owned())
                  .unwrap_or("[error detail unavailable]")
                })
                .join("\n")
              progress_message(target + ": failed: " + detail)
              save_diagnostic(
                "recover",
            }
            raise AdapterError("Tunnel workspace ownership changed")
          }
          Some(Json::String("workspace-stopped" | "workspace-busy" | "paused")) =>
            ()
